const philosophers = [
  {id:1,name:"Socrates",era:"Yunani Kuno",years:"469-399 SM",summary:"Mengubah filsafat menjadi pemeriksaan dialogis atas hidup manusia.",background:"Athena abad ke-5 SM: demokrasi, perang Peloponnesos, dan kompetisi para sofis membuat retorika menjadi kekuatan politik.",genealogy:"Dipengaruhi pertanyaan filsuf alam dan sofis, tetapi menolak relativisme mereka. Plato mewariskan citranya; ia dikritik karena tidak meninggalkan tulisan.",branches:["Epistemologi: aporia dan pengakuan atas ketidaktahuan menjadi awal pengetahuan.","Etika: hidup baik bukan akumulasi harta, melainkan perawatan jiwa melalui pemeriksaan diri.","Politik dan retorika: dialog terbuka menantang opini mayoritas dan kepakaran palsu."],works:["Apologia - pembelaan Socrates di pengadilan Athena.","Dialog Plato - rekonstruksi metode elenchos dan pencarian definisi."],quote:"The unexamined life is not worth living."},
  {id:2,name:"Plato",era:"Yunani Kuno",years:"427-347 SM",summary:"Membangun metafisika Ide dan teori negara untuk menjawab krisis polis.",background:"Athena pascaperang Peloponnesos mengalami krisis demokrasi; eksekusi Socrates menjadi trauma politik bagi generasinya.",genealogy:"Meneruskan Socrates, mengkritik sofisme, lalu memengaruhi Aristoteles. Teori Ide dikritik Aristoteles karena memisahkan bentuk dari benda konkret.",branches:["Metafisika: Dunia Ide memberi ukuran tetap bagi dunia yang berubah.","Epistemologi: pendidikan adalah pembalikan arah jiwa dari bayangan menuju pengetahuan.","Politik dan seni: filsuf-raja memimpin polis, sementara seni perlu diuji dampaknya pada jiwa."],works:["Republic - keadilan jiwa, pendidikan penjaga, dan negara ideal.","Symposium - eros sebagai gerak dari keindahan tubuh menuju keindahan pengetahuan."],quote:"Thinking is the talking of the soul with itself."},
  {id:3,name:"Aristotle",era:"Yunani Kuno",years:"384-322 SM",summary:"Menyusun ensiklopedia awal tentang alam, logika, politik, dan etika kebajikan.",background:"Dunia polis dan kerajaan Makedonia mempertemukan riset alam, variasi konstitusi, dan perubahan bentuk kewargaan.",genealogy:"Murid Plato yang mengkritik Dunia Ide terpisah; karyanya menjadi fondasi skolastisisme, ilmu alam, dan teori kebajikan.",branches:["Metafisika dan hylomorphism: setiap benda adalah komposisi materi dan bentuk, bukan bayangan pasif.","Jiwa dan psyche: jiwa adalah aktualitas tubuh hidup; anima vegetatif, sensitif, dan rasional menjelaskan kehidupan.","Retorika: ethos, pathos, dan logos menjelaskan bagaimana persuasi bekerja dalam ruang publik.","Politik: manusia adalah zoon politikon; polis memungkinkan kehidupan yang baik.","Etika: eudaimonia dicapai melalui kebiasaan kebajikan dan golden mean, bukan ekstrem."],works:["Metaphysics - penyelidikan tentang being qua being dan sebab pertama.","Nicomachean Ethics - kebahagiaan, karakter, persahabatan, dan kebajikan.","Politics - bentuk negara, kewargaan, dan kritik atas rezim yang menyimpang."],quote:"Knowing yourself is the beginning of all wisdom."},
  {id:4,name:"Epicurus",era:"Yunani Kuno",years:"341-270 SM",summary:"Memindahkan pusat kebahagiaan dari ambisi publik menuju ketenangan dan persahabatan.",background:"Setelah runtuhnya polis klasik, individu hidup dalam dunia kerajaan besar yang terasa jauh dari kendali warga.",genealogy:"Mengembangkan atomisme Demokritos dan mengkritik ketakutan religius; Stoik dan pemikir Kristen kemudian menentangnya.",branches:["Fisika: atom bergerak dalam kekosongan; clinamen memberi ruang bagi ketidakpastian dan kebebasan.","Etika: pleasure berarti ataraxia dan aponia, yaitu bebas dari kecemasan dan nyeri, bukan pesta tanpa batas.","Politik: hidup tersembunyi dan komunitas sahabat lebih aman daripada mengejar kuasa."],works:["Letter to Menoeceus - ringkasan terapi filosofis untuk hidup tenang.","Principal Doctrines - prinsip tentang hasrat, kematian, dan keadilan."],quote:"Death is nothing to us."},
  {id:5,name:"Zeno dari Citium",era:"Yunani Kuno",years:"334-262 SM",summary:"Merumuskan Stoisisme: kebebasan batin melalui hidup selaras dengan logos.",background:"Krisis polis dan pemerintahan Helenistik mendorong gagasan kosmopolitan yang melampaui batas kota.",genealogy:"Dipengaruhi Cynic dan Socrates; dikembangkan Chrysippus dan dikritik Epicurus karena terlalu menekankan kewajiban.",branches:["Logika: bahasa dan penalaran adalah alat untuk membedakan kesan dari pengetahuan.","Fisika: kosmos hidup ditata logos dan takdir; manusia adalah bagian dari keseluruhan rasional.","Etika: kebajikan satu-satunya kebaikan; emosi destruktif diolah melalui penilaian yang jernih.","Politik: kosmopolis menyatakan semua manusia berbagi rasio dan martabat."],works:["Republic - rancangan komunitas kosmopolitan yang menolak status sosial konvensional.","Discourses Stoik - ajaran yang diwariskan melalui Epictetus, Seneca, dan Marcus Aurelius."],quote:"Well-being is realized by small steps, but is truly no small thing."},
  {id:6,name:"Al-Farabi",era:"Abad Pertengahan / Islam",years:"c. 872-950",summary:"Menyatukan warisan Plato-Aristoteles dengan teori kebahagiaan dan masyarakat utama.",background:"Era Abbasiyah ditandai gerakan penerjemahan, kota intelektual, patronase istana, dan debat antara filsafat dengan teologi.",genealogy:"Mengolah Aristoteles dan Plato, lalu membuka jalan bagi Ibn Sina. Kritik teologis menyoal batas demonstrasi filosofis.",branches:["Metafisika: tatanan wujud dan emanasi menghubungkan intelek dengan kosmos.","Politik: kota utama diarahkan pemimpin berilmu menuju kebahagiaan bersama.","Musik dan bahasa: bentuk seni mengatur jiwa dan membantu pendidikan etis."],works:["Ihsa al-Ulum - klasifikasi ilmu dari bahasa dan logika hingga metafisika.","Ara Ahl al-Madina al-Fadila - teori kota utama dan kepemimpinan filosofis."],quote:"A logical mind seeks unity between reason and virtue."},
  {id:7,name:"Ibn Sina (Avicenna)",era:"Abad Pertengahan / Islam",years:"980-1037",summary:"Mengembangkan ontologi esensi-eksistensi dan filsafat kedokteran yang sistematis.",background:"Dunia Persia-Islam memiliki patronase istana, jaringan madrasah, dan ilmu kedokteran yang maju.",genealogy:"Menyempurnakan Aristoteles dan Al-Farabi; Al-Ghazali mengkritik sebagian metafisikanya, sementara Latin skolastik menyerapnya.",branches:["Ontologi: esensi sesuatu tidak otomatis ada; eksistensi aktual memerlukan sebab.","Wajib al-Wujud: realitas niscaya menjadi dasar bagi wujud kontingen.","Jiwa: thought experiment manusia melayang menunjukkan kesadaran diri yang tidak bergantung langsung pada indra.","Kedokteran: diagnosis dan observasi disusun sebagai ilmu praktis, bukan sekadar tradisi."],works:["Al-Shifa - ensiklopedia filsafat, logika, ilmu alam, dan metafisika.","Al-Qanun fi al-Tibb - sintesis teori dan praktik kedokteran yang berpengaruh berabad-abad."],quote:"The knowledge of anything is not complete unless it is known by its causes."},
  {id:8,name:"Al-Ghazali",era:"Abad Pertengahan / Islam",years:"1058-1111",summary:"Menggunakan skeptisisme untuk menguji kepastian filsafat dan memulihkan dimensi etis spiritual.",background:"Abad ke-11 menyaksikan ketegangan politik Seljuk, institusi pendidikan baru, dan kompetisi filsafat dengan teologi.",genealogy:"Menguasai filsafat Ibn Sina lalu mengkritiknya; pemikirannya memengaruhi tasawuf, teologi, dan debat tentang kausalitas.",branches:["Epistemologi: krisis keraguan memaksa pencarian pengetahuan yang lebih pasti daripada sensasi.","Kausalitas: hubungan sebab-akibat tidak niscaya secara logis; keteraturan bergantung pada kehendak Tuhan.","Etika: pengetahuan harus mengubah jiwa melalui disiplin, niat, dan praktik spiritual.","Kritik filsafat: akal berguna, tetapi tidak boleh mengklaim menjelaskan seluruh realitas."],works:["The Incoherence of the Philosophers - kritik terhadap metafisika para filsuf.","Deliverance from Error - autobiografi intelektual tentang skeptisisme dan pencarian kepastian."],quote:"The aim of knowledge is action."},
  {id:9,name:"Thomas Aquinas",era:"Abad Pertengahan / Islam",years:"1225-1274",summary:"Membangun sintesis Aristotelian antara akal, hukum alam, dan teologi Kristen.",background:"Universitas Eropa abad ke-13 menjadi arena perjumpaan Aristoteles, penerjemahan Arab, hukum gereja, dan politik kepausan.",genealogy:"Menyerap Aristoteles dan Ibn Sina, berdialog dengan Augustinus, serta dikritik oleh voluntarisme dan nominalisme.",branches:["Metafisika: analogi being dan act-potency menjelaskan ketergantungan wujud.","Etika: hukum alam mengarahkan kehendak pada kebaikan dan tujuan manusia.","Politik: hukum positif harus berpartisipasi dalam keadilan, bukan sekadar perintah penguasa.","Teologi dan akal: demonstrasi rasional mendukung, tetapi tidak menggantikan, wahyu."],works:["Summa Theologiae - sistem teologi tentang Tuhan, moralitas, dan sakramen.","De Ente et Essentia - analisis hubungan esensi dan eksistensi."],quote:"To one who has faith, no explanation is necessary."},
  {id:10,name:"Rene Descartes",era:"Modern",years:"1596-1650",summary:"Menjadikan keraguan metodis dan cogito sebagai titik awal filsafat modern.",background:"Revolusi ilmiah, konflik agama, dan runtuhnya otoritas skolastik menuntut metode pengetahuan yang baru.",genealogy:"Mengkritik skolastisisme; rasionalismenya memengaruhi Spinoza dan Leibniz, tetapi dualismenya ditantang filsafat tubuh.",branches:["Epistemologi: meragukan semua yang mungkin salah untuk menemukan kepastian cogito.","Metafisika: dualisme res cogitans dan res extensa memisahkan pikiran dari tubuh.","Metode ilmiah: analisis dan deduksi memberi urutan kerja bagi ilmu modern.","Etika: kebebasan bergantung pada kejernihan pengetahuan dan pengaturan hasrat."],works:["Discourse on the Method - autobiografi metode keraguan dan penalaran.","Meditations - cogito, Tuhan, pikiran, dan dunia material."],quote:"I think, therefore I am."},
  {id:11,name:"Baruch Spinoza",era:"Modern",years:"1632-1677",summary:"Menyamakan Tuhan dan Alam dalam monisme yang menantang agama, kehendak bebas, dan negara.",background:"Republik Belanda menawarkan toleransi relatif, tetapi sensor agama dan konflik komunitas tetap kuat.",genealogy:"Mengembangkan rasionalisme Descartes dan geometri Euclid; dikutuk komunitas Yahudi dan memengaruhi pencerahan serta Nietzsche.",branches:["Ontologi: hanya ada satu substansi, Deus sive Natura; pikiran dan tubuh adalah atribut berbeda.","Etika: manusia bebas ketika memahami sebab yang menentukan dirinya, bukan ketika merasa tanpa sebab.","Politik: kebebasan berpikir menjaga negara; otoritas agama tidak boleh memonopoli kebenaran.","Afek: conatus dan pemahaman kausal mengubah pasivitas menjadi daya bertindak."],works:["Ethics - metafisika, emosi, dan kebebasan dalam bentuk deduktif geometris.","Theological-Political Treatise - kritik otoritas kitab dan pembelaan kebebasan berpikir."],quote:"Peace is not an absence of war; it is a virtue."},
  {id:12,name:"John Locke",era:"Modern",years:"1632-1704",summary:"Mendasarkan pengetahuan pada pengalaman dan politik pada hak serta persetujuan warga.",background:"Inggris mengalami perang saudara, Restorasi, dan Glorious Revolution yang membentuk debat tentang legitimasi kuasa.",genealogy:"Menanggapi rasionalisme dan gagasan bawaan; liberalismenya menjadi sasaran kritik Marx dan teori komunitarian.",branches:["Epistemologi: pikiran adalah tabula rasa; ide kompleks dibangun dari sensasi dan refleksi.","Politik: hak hidup, kebebasan, dan properti membatasi pemerintah.","Agama: toleransi dibutuhkan, tetapi batasnya diperdebatkan dalam konteks politik abad ke-17.","Bahasa: kata adalah tanda ide, sehingga penyalahgunaan istilah mengacaukan pengetahuan."],works:["An Essay Concerning Human Understanding - asal-usul, batas, dan derajat pengetahuan.","Two Treatises of Government - kritik absolutisme dan teori pemerintahan berdasarkan persetujuan."],quote:"New opinions are always suspected, and usually opposed, without any other reason but because they are not already common."},
  {id:13,name:"Immanuel Kant",era:"Modern",years:"1724-1804",summary:"Menyintesiskan rasionalisme dan empirisme dengan revolusi Copernican dalam teori pengetahuan.",background:"Pencerahan Eropa mempertemukan sains Newtonian, empirisme Inggris, dan krisis metafisika dogmatis.",genealogy:"Dibangunkan dari dogmatisme oleh Hume; memengaruhi Hegel, idealisme, teori moral, dan kritik kolonial yang masih diperdebatkan.",branches:["Epistemologi: kategori a priori pikiran menyusun pengalaman; kita mengenal fenomena, bukan noumena secara langsung.","Etika: imperatif kategoris mewajibkan manusia diperlakukan sebagai tujuan, bukan alat.","Estetika: penilaian keindahan menjembatani kebebasan dan alam melalui purposiveness tanpa tujuan.","Politik: perdamaian abadi memerlukan republik, hukum kosmopolitan, dan hubungan antarnegara."],works:["Critique of Pure Reason - batas pengalaman, kategori, dan antinomi akal.","Groundwork of the Metaphysics of Morals - dasar rasional kewajiban dan otonomi."],quote:"Dare to know! Have courage to use your own reason."},
  {id:14,name:"G.W.F. Hegel",era:"Modern",years:"1770-1831",summary:"Membaca sejarah sebagai gerak dialektis kesadaran, konflik, dan pengakuan.",background:"Revolusi Prancis dan perubahan negara modern menantang gagasan linear tentang kemajuan serta kebebasan.",genealogy:"Mengembangkan Kant dan idealisme Jerman; Marx membalik dialektikanya menjadi materialisme historis.",branches:["Dialektika: kontradiksi bukan kesalahan belaka, tetapi motor perkembangan konsep dan sejarah.","Fenomenologi: kesadaran menjadi diri melalui pengakuan, terutama dalam dialektika tuan-budak.","Sejarah: kebebasan berkembang melalui institusi sosial, bukan hanya kehendak individual.","Seni dan agama: keduanya menyingkap roh, tetapi filsafat memberi bentuk konseptual tertinggi."],works:["Phenomenology of Spirit - perjalanan kesadaran dari pengalaman menuju pengetahuan.","Philosophy of Right - keluarga, masyarakat sipil, negara, dan kebebasan objektif."],quote:"The truth is the whole."},
  {id:15,name:"Friedrich Nietzsche",era:"Postmodern / Kontemporer",years:"1844-1900",summary:"Membongkar moralitas dan kebenaran sebagai hasil sejarah, tubuh, dan kehendak.",background:"Industrialisasi, sekularisasi, nasionalisme, dan krisis agama mengguncang nilai Eropa abad ke-19.",genealogy:"Mengkritik Plato, moralitas Kristen, dan Wagner; memengaruhi eksistensialisme, psikoanalisis, dan genealogi Foucault.",branches:["Genealogi moral: baik dan jahat lahir dari konflik nilai, ressentiment, serta relasi kekuatan.","Ontologi: kehendak untuk berkuasa membaca hidup sebagai proses interpretasi dan penciptaan bentuk.","Etika: amor fati dan pengujian eterno retorno menuntut afirmasi hidup tanpa jaminan transenden.","Seni: tragedi menerima penderitaan dan kontradiksi, tidak menutupinya dengan rasionalisme."],works:["Thus Spoke Zarathustra - figur Ubermensch dan afirmasi penciptaan nilai.","On the Genealogy of Morality - sejarah hukuman, rasa bersalah, dan moralitas budak."],quote:"He who has a why to live can bear almost any how."},
  {id:16,name:"Karl Marx",era:"Postmodern / Kontemporer",years:"1818-1883",summary:"Menjelaskan sejarah melalui produksi material, konflik kelas, dan pengalaman alienasi.",background:"Kapitalisme industri memperluas pabrik, urbanisasi, kemiskinan, dan gerakan buruh di Eropa abad ke-19.",genealogy:"Membalik dialektika Hegel, menyerap kritik ekonomi politik dan sosialisme; dikritik karena determinisme dan reduksi kelas.",branches:["Materialisme historis: mode produksi membentuk institusi, hukum, dan kesadaran sosial.","Alienasi: pekerja terpisah dari produk, proses kerja, sesama manusia, dan potensi dirinya.","Ideologi: gagasan dominan sering menormalkan kepentingan kelas yang dominan.","Politik: emansipasi membutuhkan perubahan relasi kepemilikan dan praktik kolektif."],works:["Capital - kritik komoditas, nilai lebih, dan dinamika akumulasi kapital.","The Communist Manifesto - sejarah kelas dan program politik gerakan komunis."],quote:"The philosophers have only interpreted the world; the point is to change it."},
  {id:17,name:"Jean-Paul Sartre",era:"Postmodern / Kontemporer",years:"1905-1980",summary:"Menempatkan kebebasan, pilihan, dan tanggung jawab di tengah dunia tanpa esensi tetap.",background:"Perang dunia, pendudukan, dan krisis politik Eropa membentuk eksistensialisme sebagai filsafat tanggung jawab.",genealogy:"Mengolah fenomenologi Husserl dan Heidegger; dikritik karena kebebasan individual perlu dibaca bersama struktur sosial.",branches:["Ontologi: eksistensi mendahului esensi; manusia menjadi dirinya melalui pilihan dan proyek.","Kebebasan: tidak memilih pun adalah pilihan; tanggung jawab tidak dapat dialihkan pada takdir.","Bad faith: kesadaran berbohong pada diri sendiri dengan menganggap dirinya hanya peran atau benda.","Politik: kebebasan personal berhadapan dengan kondisi material, sejarah, dan orang lain."],works:["Being and Nothingness - kesadaran, kebebasan, tatapan, dan relasi dengan orang lain.","Existentialism Is a Humanism - pembelaan ringkas atas kebebasan dan tanggung jawab."],quote:"Man is condemned to be free."},
  {id:18,name:"Michel Foucault",era:"Postmodern / Kontemporer",years:"1926-1984",summary:"Menelusuri bagaimana wacana, institusi, dan disiplin membentuk tubuh serta subjek modern.",background:"Abad ke-20 diwarnai perang, birokrasi, psikiatri, penjara, dan negara administratif yang mengatur kehidupan sehari-hari.",genealogy:"Mengembangkan genealogi Nietzsche dan mengkritik humanisme universal; diperdebatkan karena struktur kuasa tampak terlalu menyeluruh.",branches:["Disiplin tubuh: sekolah, barak, rumah sakit, dan penjara melatih tubuh lewat pengawasan dan norma.","Wacana: pengetahuan tidak netral; institusi menentukan siapa yang boleh berbicara dan apa yang dianggap benar.","Seksualitas: identitas seksual diproduksi melalui pengakuan, klasifikasi, dan praktik biopolitik.","Kuasa dan resistensi: kuasa hadir dalam relasi mikro dan selalu membuka ruang perlawanan."],works:["Discipline and Punish - lahirnya penjara, panoptikon, dan masyarakat disipliner.","The History of Sexuality - kritik atas gagasan bahwa kuasa hanya membungkam seksualitas."],quote:"Where there is power, there is resistance."}
];

const fallacies = [{name:"Ad Hominem",keywords:["bodoh","munafik","tidak layak didengar","karena kamu","karena dia"],desc:"Menyerang pribadi, bukan alasan yang diajukan.",example:"Pendapatnya salah karena dia tidak kompeten."},{name:"Strawman",keywords:["berarti kamu ingin","jadi kamu ingin","berarti dia ingin","tidak peduli sama sekali"],desc:"Mengubah posisi lawan menjadi versi ekstrem yang mudah diserang.",example:"Dia ingin anggaran dikurangi, berarti dia ingin negara hancur."},{name:"Slippery Slope",keywords:["pasti akan","otomatis akan","kalau sekali","ujung-ujungnya","efek domino"],desc:"Menganggap langkah kecil pasti memicu akibat ekstrem.",example:"Kalau bolos sekali, kamu pasti putus sekolah."},{name:"Circular Reasoning",keywords:["benar karena","pasti benar sebab","sah karena memang sah"],desc:"Kesimpulan dipakai sebagai alasan bagi dirinya sendiri.",example:"Aturan ini benar karena aturan ini menyatakan dirinya benar."},{name:"False Dilemma",keywords:["hanya ada dua pilihan","setuju denganku atau","mendukung atau melawan","antara ini atau itu"],desc:"Seolah hanya ada dua pilihan padahal alternatifnya lebih banyak.",example:"Kamu setuju denganku atau berarti musuhku."},{name:"Appeal to Authority",keywords:["kata ahli","selebritas bilang","profesor itu bilang","karena tokoh"],desc:"Menganggap klaim pasti benar hanya karena datang dari figur berwenang.",example:"Produk ini pasti aman karena dipromosikan tokoh terkenal."}];
let selectedEra = "Semua Era"; let selectedPhilosopher = null;
document.addEventListener("DOMContentLoaded", () => { applySavedTheme(); setTimeout(() => document.getElementById("splash-screen")?.classList.add("fade-out"), 1600); renderEraFilters(); renderPhilosophers(); renderFallacies(); document.getElementById("fallacy-search")?.addEventListener("input", renderFallacies); });
function applySavedTheme() { const theme = localStorage.getItem("philosofun-theme") || "light"; document.documentElement.dataset.theme = theme; updateThemeIcon(); }
function toggleTheme() { document.documentElement.dataset.theme = document.documentElement.dataset.theme === "dark" ? "light" : "dark"; localStorage.setItem("philosofun-theme", document.documentElement.dataset.theme); updateThemeIcon(); }
function updateThemeIcon() { const icon = document.querySelector("#theme-toggle i"); if (icon) icon.className = document.documentElement.dataset.theme === "dark" ? "fa-solid fa-sun" : "fa-solid fa-moon"; }
function renderEraFilters() { const bar = document.getElementById("era-filters"); const eras = ["Semua Era", ...new Set(philosophers.map(philosopher => philosopher.era))]; bar.innerHTML = eras.map(era => `<button class="era-filter${era === selectedEra ? " active" : ""}" data-era="${era}">${era}</button>`).join(""); bar.querySelectorAll("button").forEach(button => button.addEventListener("click", () => { selectedEra = button.dataset.era; renderEraFilters(); renderPhilosophers(); })); }
function renderPhilosophers() { const grid = document.getElementById("philosopher-grid"); const visible = selectedEra === "Semua Era" ? philosophers : philosophers.filter(philosopher => philosopher.era === selectedEra); document.getElementById("result-count").textContent = `${visible.length} tokoh`; grid.innerHTML = visible.map(philosopher => `<article class="philosopher-card${selectedPhilosopher?.id === philosopher.id ? " selected" : ""}" data-id="${philosopher.id}"><div class="avatar">${philosopher.name.split(" ").map(word => word[0]).slice(0,2).join("")}</div><span class="card-era">${philosopher.era}</span><h3>${philosopher.name}</h3><span class="card-years">${philosopher.years}</span><p class="card-summary">${philosopher.summary}</p></article>`).join(""); grid.querySelectorAll(".philosopher-card").forEach(card => card.addEventListener("click", () => showPhilosopherDetail(Number(card.dataset.id)))); }
function showOldDetail1(id) { selectedPhilosopher = philosophers.find(philosopher => philosopher.id === id); if (!selectedPhilosopher) return; document.getElementById("detail-empty").classList.add("hidden"); document.getElementById("detail-content").classList.remove("hidden"); document.getElementById("detail-era").textContent = selectedPhilosopher.era; document.getElementById("detail-name").textContent = selectedPhilosopher.name; document.getElementById("detail-years").textContent = selectedPhilosopher.years; document.getElementById("detail-sections").innerHTML = `<div class="detail-block"><h4>Latar belakang sosial-politik</h4><p>${selectedPhilosopher.background}</p></div><div class="detail-block"><h4>Genealogi pemikiran</h4><p>${selectedPhilosopher.genealogy}</p></div><div class="detail-block"><h4>Cabang pemikiran radikal</h4>${selectedPhilosopher.branches.map(branch => `<p>${branch}</p>`).join("")}</div><div class="detail-block detail-works"><h4>Literatur magnum opus</h4>${selectedPhilosopher.works.map(work => `<p>${work}</p>`).join("")}</div>`; document.getElementById("detail-quote").textContent = `"${selectedPhilosopher.quote}"`; document.getElementById("copy-quote").dataset.quote = selectedPhilosopher.quote; document.getElementById("share-quote").dataset.quote = selectedPhilosopher.quote; renderPhilosophers(); document.getElementById("philosopher-detail").scrollIntoView({behavior:"smooth",block:"nearest"}); }
function closePhilosopherDetail() { selectedPhilosopher = null; document.getElementById("detail-content").classList.add("hidden"); document.getElementById("detail-empty").classList.remove("hidden"); renderPhilosophers(); }
function switchTab(tab) { document.querySelectorAll(".tab-content").forEach(element => element.classList.add("hidden")); document.querySelectorAll(".nav-button").forEach(element => element.classList.remove("active")); document.getElementById(`tab-${tab}`)?.classList.remove("hidden"); document.getElementById(`nav-${tab}`)?.classList.add("active"); }
function renderFallacies() { const query = (document.getElementById("fallacy-search")?.value || "").toLowerCase(); const items = fallacies.filter(fallacy => `${fallacy.name} ${fallacy.desc} ${fallacy.example}`.toLowerCase().includes(query)); document.getElementById("fallacy-grid").innerHTML = items.length ? items.map(fallacy => `<article class="fallacy-card"><p class="eyebrow">Logical fallacy</p><h3>${fallacy.name}</h3><p>${fallacy.desc}</p><div class="fallacy-example"><strong>Contoh sehari-hari</strong>${fallacy.example}</div></article>`).join("") : "<p>Tidak ada hasil untuk pencarian ini.</p>"; }
function analyzeArgument(event) { event.preventDefault(); const text = document.getElementById("argument-input").value.toLowerCase(); const matches = fallacies.filter(fallacy => fallacy.keywords.some(keyword => text.includes(keyword))); const box = document.getElementById("fallacy-result"); box.classList.remove("hidden", "result-valid", "result-invalid"); box.classList.add(matches.length ? "result-invalid" : "result-valid"); box.innerHTML = matches.length ? `<strong><i class="fa-solid fa-triangle-exclamation"></i> ${matches.length} pola terdeteksi</strong><p>${matches.map(match => `<b>${match.name}</b>: ${match.desc}`).join("<br>")}</p><small>Ini adalah indikasi awal. Periksa konteks dan bukti sebelum mengambil kesimpulan.</small>` : "<strong><i class=\"fa-solid fa-circle-check\"></i> Tidak ada pola umum terdeteksi</strong><p>Tidak ada keyword fallacy yang cocok. Argumen tetap perlu diuji berdasarkan bukti dan relevansi.</p>"; }
function words(text) { return text.toLowerCase().replace(/[^a-z0-9\s]/g, " ").split(/\s+/).filter(word => word.length > 3); }
function analyzeSyllogism(event) { event.preventDefault(); const major = new Set(words(document.getElementById("p1").value)); const minor = new Set(words(document.getElementById("p2").value)); const conclusion = new Set(words(document.getElementById("conc").value)); const middle = [...major].filter(word => minor.has(word) && !conclusion.has(word)); const linked = [...conclusion].filter(word => major.has(word) || minor.has(word)); const valid = middle.length > 0 && linked.length > 0; const box = document.getElementById("logic-result"); box.classList.remove("hidden", "result-valid", "result-invalid"); box.classList.add(valid ? "result-valid" : "result-invalid"); box.innerHTML = valid ? `<strong><i class="fa-solid fa-circle-check"></i> Struktur dasar valid</strong><p>Term tengah "${middle.join(", ")}" muncul di kedua premis dan tidak muncul di kesimpulan. Ada term yang menghubungkan premis dengan kesimpulan.</p>` : `<strong><i class="fa-solid fa-circle-xmark"></i> Struktur invalid</strong><p>Term tengah tidak ditemukan dengan jelas di kedua premis, atau kesimpulan tidak terhubung dengan premis. Periksa kembali distribusi term.</p>`; }
function copyQuote() { const quote = document.getElementById("copy-quote").dataset.quote; navigator.clipboard?.writeText(quote).then(() => { const button = document.getElementById("copy-quote"); button.textContent = "Tersalin"; setTimeout(() => { button.innerHTML = '<i class="fa-regular fa-copy"></i> Copy Quote'; }, 1300); }); }
function shareQuote() { const quote = document.getElementById("share-quote").dataset.quote; if (navigator.share) navigator.share({title:"Philosofun",text:quote}); else navigator.clipboard?.writeText(quote); }
function openAuthModal() { document.getElementById("auth-modal").classList.remove("hidden"); } function closeAuthModal() { document.getElementById("auth-modal").classList.add("hidden"); } function switchAuthTab(type) { const login = type === "login"; document.getElementById("form-login").classList.toggle("hidden", !login); document.getElementById("form-register").classList.toggle("hidden", login); document.getElementById("btn-login-tab").classList.toggle("active", login); document.getElementById("btn-register-tab").classList.toggle("active", !login); }
function handleAuth(event, type) { event.preventDefault(); const name = document.getElementById(type === "login" ? "login-username" : "reg-name").value; document.getElementById("user-area").innerHTML = `<div class="auth-button"><i class="fa-solid fa-circle-user"></i> ${name}</div>`; closeAuthModal(); }
import { philosophersData } from "./data/index.js";

const modularPhilosophers = new Map(philosophersData.map(philosopher => [philosopher.id, philosopher]));
function markAcademicTerms(html) { const terms = ["Wajib al-Wujud", "al-'Aql al-Fa'al", "hylomorphism", "eudaimonia", "imperatif kategoris", "panoptikon", "biopolitik", "materialisme historis", "alienasi", "Dunia Ide", "cogito", "res cogitans", "res extensa", "Deus sive Natura", "conatus", "ataraxia", "akrasia", "logos"]; return terms.reduce((content, term) => content.replace(new RegExp(`(?<![\\w>])${term}(?![\\w<])`, "gi"), `<em>${term}</em>`), html); }
const extendedNotes = {
  1: `<h3>Contoh Historis dan Relevansi</h3><p class="mb-4 leading-relaxed">Ketika Socrates bertanya kepada seorang politikus Athena tentang arti keadilan, ia tidak sedang melakukan kuis definisi. Ia memperlihatkan bahwa keputusan tentang perang, hukuman, dan pendidikan dibuat oleh orang yang sering tidak mampu menjelaskan standar tindakannya sendiri. Metode ini tetap relevan ketika opini publik digital bergerak lebih cepat daripada pemeriksaan bukti.</p><p class="mb-4 leading-relaxed">Dengan demikian, elenchos adalah praktik politik mikro. Ia mengubah percakapan dari adu status menjadi pemeriksaan alasan, sekaligus memperlihatkan bahwa kerendahan hati epistemik memiliki konsekuensi institusional: warga yang mengakui ketidaktahuannya lebih mungkin meminta prosedur, saksi, dan alasan yang dapat diuji.</p>`,
  2: `<h3>Contoh Historis dan Relevansi</h3><p class="mb-4 leading-relaxed">Allegory of the Cave dapat dibaca sebagai analisis tentang bagaimana institusi membentuk apa yang tampak nyata. Orang yang hanya melihat bayangan tidak sekadar kekurangan data; seluruh kategori penilaiannya dibentuk oleh ruang tempat ia hidup. Pendidikan filosofis karena itu sering terasa menyakitkan karena memaksa perubahan orientasi, bukan hanya penambahan informasi.</p><p class="mb-4 leading-relaxed">Kritik Plato terhadap demokrasi juga perlu dibaca secara hati-hati. Ia tidak hanya mengatakan rakyat bodoh, melainkan menanyakan bagaimana hasrat, retorika, dan insentif media dapat menggantikan pengetahuan. Masalah ini terlihat dalam politik modern ketika popularitas seorang pembicara lebih menentukan daripada kompetensi kebijakan.</p>`,
  3: `<h3>Contoh Historis dan Relevansi</h3><p class="mb-4 leading-relaxed">Analisis Aristotle tentang retorika menjelaskan mengapa sebuah klaim medis dapat dipercaya karena reputasi dokter, emosi pasien, dan struktur buktinya sekaligus. Ethos, pathos, dan logos bukan hiasan pidato, tetapi tiga dimensi penerimaan publik yang harus diawasi agar persuasi tidak berubah menjadi manipulasi.</p><p class="mb-4 leading-relaxed">Etika golden mean juga bukan ajakan untuk selalu moderat. Dalam keadaan penindasan, “jalan tengah” antara melawan dan menyerah dapat menjadi keburukan. Phronesis menuntut pembacaan situasi: kebajikan adalah kemampuan memilih tindakan yang tepat bagi tujuan manusiawi dalam keadaan konkret.</p>`,
  4: `<h3>Contoh Historis dan Relevansi</h3><p class="mb-4 leading-relaxed">Terapi Epicurus dapat diterapkan pada budaya konsumsi yang mengubah keinginan menjadi kebutuhan tanpa akhir. Pembedaan hasrat alamiah dan hasrat sia-sia membantu menjelaskan mengapa kenaikan pendapatan tidak otomatis mengurangi kecemasan: mekanisme sosial terus menciptakan standar baru tentang status.</p><p class="mb-4 leading-relaxed">Pandangan tentang kematian juga bukan penyangkalan duka. Argumennya membedakan pengalaman hidup dari keadaan tidak mengalami, sehingga ketakutan metafisik tidak menguasai seluruh hidup. Persahabatan di Garden menjadi contoh bagaimana terapi filosofis membutuhkan komunitas, bukan sekadar keyakinan individual.</p>`,
  5: `<h3>Contoh Historis dan Relevansi</h3><p class="mb-4 leading-relaxed">Stoic distinction between what is and is not in our control dapat terlihat dalam krisis politik: seseorang tidak menguasai hasil pemilu, tetapi menguasai cara memeriksa kabar, memilih tindakan, dan memperlakukan lawan. Ini bukan pasrah, karena kewajiban bertindak tetap berada dalam wilayah kendali.</p><p class="mb-4 leading-relaxed">Kosmopolitanisme Stoik juga memberi dasar awal bagi gagasan kewargaan dunia. Namun sejarah perbudakan dan kekaisaran menunjukkan jarak antara prinsip universal dan institusi nyata. Justru jarak tersebut menjadi bahan kritik: kebajikan universal harus diterjemahkan menjadi hukum yang melindungi tubuh konkret.</p>`,
  6: `<h3>Contoh Historis dan Relevansi</h3><p class="mb-4 leading-relaxed">Bagi Al-Farabi, kebijakan pendidikan tidak pernah netral. Kurikulum menentukan gambaran kebahagiaan apa yang akan dikejar warga; pendidikan yang hanya melatih konsumsi dan kompetisi menciptakan kota naddalah meskipun infrastrukturnya maju.</p><p class="mb-4 leading-relaxed">Tipologinya membantu membaca negara modern yang memakai simbol moral untuk mengejar kepentingan sempit. Pertanyaan Farabian bukan hanya “siapa yang berkuasa?”, tetapi “gambaran manusia macam apa yang diproduksi oleh hukum, ritus, media, dan pemimpin tersebut?”</p>`,
  7: `<h3>Contoh Historis dan Relevansi</h3><p class="mb-4 leading-relaxed">Flying Man memberi cara untuk membedakan data tentang tubuh dari struktur kesadaran diri. Dalam ilmu kognitif kontemporer, masalah ini muncul kembali ketika peneliti bertanya apakah kesadaran dapat direduksi menjadi korelasi neural atau membutuhkan analisis first-person.</p><p class="mb-4 leading-relaxed">Kedokteran Avicenna juga memperlihatkan bahwa pengetahuan praktis memerlukan klasifikasi dan pengalaman. Diagnosis bukan intuisi ajaib: ia menggabungkan gejala, sebab, prognosis, dan respons tubuh dalam prosedur yang dapat diajarkan.</p>`,
  8: `<h3>Contoh Historis dan Relevansi</h3><p class="mb-4 leading-relaxed">Kritik Al-Ghazali terhadap keniscayaan kausalitas dapat dibaca sebagai peringatan agar hukum alam tidak berubah menjadi metafisika dogmatis. Dalam penelitian modern, teori selalu terbuka untuk revisi meski praktik ilmiah tetap membutuhkan pola kausal yang stabil.</p><p class="mb-4 leading-relaxed">Namun occasionalism tidak menghapus tanggung jawab. Ia memindahkan perhatian dari kemampuan manusia menguasai alam kepada disiplin niat dan tindakan. Pengetahuan dinilai lengkap hanya ketika mengubah cara seseorang menghadapi kesombongan, ketakutan, dan penderitaan.</p>`,
  9: `<h3>Contoh Historis dan Relevansi</h3><p class="mb-4 leading-relaxed">Natural law Aquinas dapat membantu menilai hukum yang sah secara prosedural tetapi merusak tujuan bersama. Peraturan yang memerintahkan diskriminasi mungkin memiliki bentuk legal, namun gagal berpartisipasi dalam keadilan karena bertentangan dengan kebaikan manusia yang menjadi tujuan hukum.</p><p class="mb-4 leading-relaxed">Sintesis akal dan wahyu juga memberi model dialog lintas disiplin. Sains dapat menjelaskan mekanisme alam tanpa otomatis menyelesaikan pertanyaan tentang makna, kewajiban, atau tujuan; sebaliknya, teologi tidak boleh menggantikan pemeriksaan empiris.</p>`,
  10: `<h3>Contoh Historis dan Relevansi</h3><p class="mb-4 leading-relaxed">Keraguan metodis Descartes tampak dalam praktik keamanan digital dan sains: identitas, sensor, dan kesaksian tidak diterima hanya karena terlihat meyakinkan. Setiap klaim memerlukan prosedur verifikasi, walaupun kehidupan praktis tidak memungkinkan keraguan total.</p><p class="mb-4 leading-relaxed">Dualisme mind-body juga terus muncul ketika sistem kesehatan mengobati tubuh tetapi mengabaikan pengalaman pasien. Kritik kontemporer menolak pemisahan tajam itu, namun problem Descartes tetap produktif karena memaksa kita menjelaskan hubungan antara kesadaran subjektif dan proses material.</p>`,
  11: `<h3>Contoh Historis dan Relevansi</h3><p class="mb-4 leading-relaxed">Spinoza membantu menjelaskan bagaimana seseorang dapat merasa bebas padahal tindakannya dibentuk oleh sebab yang tidak ia pahami. Memahami algoritma rekomendasi, tekanan ekonomi, dan kebiasaan afektif tidak otomatis membebaskan, tetapi membuka kemungkinan mengubah hubungan kita dengan sebab-sebab tersebut.</p><p class="mb-4 leading-relaxed">Pembelaan atas kebebasan berpikir juga relevan bagi negara yang memakai sensor untuk menciptakan keseragaman. Bagi Spinoza, penindasan keyakinan tidak menghasilkan persatuan; ia menghasilkan kemunafikan dan mengganggu stabilitas yang justru hendak dipertahankan negara.</p>`,
  12: `<h3>Contoh Historis dan Relevansi</h3><p class="mb-4 leading-relaxed">Locke membantu menjelaskan mengapa pemerintah demokratis dianggap sebagai trustee, bukan pemilik rakyat. Ketika pajak, pengawasan, atau pembatasan kebebasan diputuskan tanpa alasan dan persetujuan yang layak, warga dapat menilai bahwa trust telah dilanggar.</p><p class="mb-4 leading-relaxed">Namun teori properti Locke juga perlu dikritik dari sudut kolonialisme dan akumulasi. Gagasan bahwa kerja membuat tanah menjadi milik dapat menghapus klaim masyarakat adat yang memiliki bentuk relasi berbeda terhadap tanah. Pembacaan akademik yang bertanggung jawab harus mempertahankan argumen hak sambil menguji asumsi eksklusinya.</p>`,
  13: `<h3>Contoh Historis dan Relevansi</h3><p class="mb-4 leading-relaxed">Imperatif kategoris mengubah pertanyaan etis dari “apa hasil yang saya inginkan?” menjadi “apakah prinsip tindakan saya dapat diterima bila semua orang menggunakannya?” Korupsi, misalnya, tidak hanya merugikan korban tertentu; ia merusak kemungkinan institusi kepercayaan jika dijadikan aturan umum.</p><p class="mb-4 leading-relaxed">Kant juga membantu menjelaskan mengapa efisiensi tidak cukup menjadi ukuran kebijakan. Manusia yang diperlakukan sebagai angka produktivitas kehilangan statusnya sebagai tujuan. Dalam politik digital, prinsip ini menuntut agar data manusia tidak dipakai semata-mata sebagai bahan optimasi.</p>`,
  14: `<h3>Contoh Historis dan Relevansi</h3><p class="mb-4 leading-relaxed">Dialektika Hegel dapat digunakan membaca perubahan sosial: tuntutan kebebasan yang awalnya berbenturan dengan institusi lama memaksa institusi mengartikulasikan norma baru. Aufhebung bukan penghapusan sederhana, karena unsur lama dapat dipertahankan dalam bentuk yang berubah.</p><p class="mb-4 leading-relaxed">Dialektika tuan-budak juga menerangkan mengapa kekuasaan yang hanya menuntut kepatuhan rapuh. Penguasa membutuhkan pengakuan dari orang yang ia rendahkan; tanpa pengakuan timbal balik, status itu tidak memperoleh legitimasi yang stabil.</p>`,
  15: `<h3>Contoh Historis dan Relevansi</h3><p class="mb-4 leading-relaxed">Genealogi Nietzsche dapat dipakai untuk bertanya dari mana standar “normal”, “sukses”, dan “bermoral” berasal. Standar itu sering tampak alamiah karena telah diulang sekolah, agama, keluarga, dan pasar, padahal ia merupakan hasil seleksi historis dan konflik kepentingan.</p><p class="mb-4 leading-relaxed">Amor fati bukan persetujuan pasif atas ketidakadilan. Ia adalah eksperimen etis untuk mengubah penderitaan menjadi bahan penciptaan diri, sedangkan kritik sosial tetap diperlukan untuk membedakan penderitaan yang tak terhindarkan dari penderitaan yang diproduksi institusi.</p>`,
  16: `<h3>Studi Kasus Radikal: Kapitalisme Industri dan Alienasi</h3><p class="mb-4 leading-relaxed">Ambil contoh pekerja pabrik tekstil abad ke-19 yang menghabiskan dua belas jam mengoperasikan satu bagian mesin. Ia menghasilkan komoditas yang tidak ia rancang, tidak ia miliki, dan tidak dapat ia konsumsi secara setara; upah hanya membeli kembali tenaga kerja agar ia dapat datang bekerja esok hari. Dalam istilah Marx, keterpisahan ini bukan perasaan pribadi semata, melainkan relasi sosial yang disusun oleh kepemilikan alat produksi.</p><p class="mb-4 leading-relaxed">Nilai lebih muncul ketika waktu kerja yang dibutuhkan untuk mengganti upah lebih pendek daripada keseluruhan waktu kerja. Jika kebutuhan hidup pekerja secara sosial membutuhkan empat jam kerja, tetapi hari kerja berlangsung sepuluh jam, selisihnya menjadi sumber surplus bagi pemilik kapital. Persaingan kemudian mendorong pemilik memperpanjang hari kerja, menurunkan biaya, atau memasukkan mesin baru; krisis bukan kecelakaan eksternal, melainkan kecenderungan yang lahir dari logika akumulasi.</p><h3>Ideologi, Komoditas, dan Kehidupan Sehari-hari</h3><p class="mb-4 leading-relaxed">Komoditas menyembunyikan hubungan sosial di balik hubungan benda. Harga sebuah telepon, pakaian, atau layanan digital tampak seperti sifat alamiah objek, padahal di dalamnya terkandung rantai kerja, ekstraksi bahan, logistik, dan keputusan kepemilikan. Inilah commodity fetishism: manusia melupakan bahwa nilai dan kuasa muncul dari hubungan sosial, lalu memperlakukan pasar seolah-olah memiliki kehendak sendiri.</p><p class="mb-4 leading-relaxed">Ideologi bekerja bukan hanya sebagai propaganda yang sengaja dibuat. Ia hidup sebagai common sense: keyakinan bahwa siapa pun dapat sukses bila cukup rajin, bahwa pengangguran semata-mata kegagalan karakter, atau bahwa pilihan konsumen otomatis adalah kebebasan politik. Kritik Marx membongkar kondisi material yang membuat beberapa pilihan tersedia bagi satu kelas tetapi tidak bagi kelas lain.</p><h3>Praksis dan Emansipasi</h3><p class="mb-4 leading-relaxed">Bagi Marx, filsafat tidak berhenti pada interpretasi. Praksis berarti kesatuan teori dan transformasi: analisis tentang eksploitasi harus mengubah organisasi, hukum, dan pembagian kerja. Emansipasi bukan sekadar mengganti penguasa, melainkan mengubah struktur yang memaksa manusia menjual tenaga hidupnya sebagai komoditas.</p><p class="mb-4 leading-relaxed">Contoh kontemporernya tampak dalam ekonomi platform, ketika pekerja disebut mitra tetapi algoritma menentukan tarif, urutan pekerjaan, evaluasi, dan risiko. Bahasa kebebasan kontraktual dapat menutupi ketergantungan material. Analisis Marx membantu mengajukan pertanyaan yang lebih tajam: siapa memiliki infrastruktur, siapa mengendalikan data, siapa menanggung risiko, dan siapa menerima nilai yang dihasilkan?</p>`,
  17: `<h3>Contoh Historis dan Relevansi</h3><p class="mb-4 leading-relaxed">Bad faith dapat terlihat ketika seseorang menyatakan “saya memang begini” untuk menghindari tanggung jawab, atau ketika institusi mengaku hanya mengikuti prosedur seolah-olah prosedur tidak pernah dipilih manusia. Sartre tidak menolak fakta sosial; ia menolak penggunaan fakta sebagai alasan untuk meniadakan kemungkinan bertindak.</p><p class="mb-4 leading-relaxed">Dalam politik, kebebasan harus dipahami bersama situasi material. Orang yang lapar, dijajah, atau didiskriminasi tetap memiliki kesadaran, tetapi ruang proyeknya menyempit. Eksistensialisme menjadi lebih kuat ketika digabung dengan kritik kelas, gender, dan kolonialisme yang menunjukkan siapa yang dibebani tanggung jawab tanpa diberi kemampuan setara.</p>`,
  18: `<h3>Contoh Historis dan Relevansi</h3><p class="mb-4 leading-relaxed">Panoptikon dapat dibaca dalam sekolah yang terus menguji ranking, kantor yang mencatat produktivitas, dan platform yang memberi skor reputasi. Tidak diperlukan pengawas yang hadir setiap saat; kemungkinan dinilai membuat individu mengatur tubuh dan perilakunya sendiri sesuai norma yang tidak selalu terlihat.</p><p class="mb-4 leading-relaxed">Dalam wacana seksualitas, formulir, diagnosis, konten media, dan prosedur pengakuan dapat mengubah pengalaman privat menjadi identitas yang harus dijelaskan. Resistensi tidak berarti berdiri di luar kuasa, tetapi menciptakan cara bicara, praktik tubuh, dan hubungan sosial yang mengganggu kategori dominan.</p>`
};
philosophersData.forEach(philosopher => { philosopher.contentHtml = markAcademicTerms(philosopher.contentHtml + (extendedNotes[philosopher.id] || "")); });
const originalAcademicProfile = getAcademicProfile;
function getLegacyAcademicProfile(philosopher) { const modular = modularPhilosophers.get(philosopher.id); if (!modular) return originalAcademicProfile(philosopher); return { background: philosopher.background, genealogy: philosopher.genealogy, branches: [{ title: "Kajian akademik lengkap", paragraphs: [modular.contentHtml] }], works: [] }; }
function showPhilosopherDetail(id) { selectedPhilosopher = philosophers.find(philosopher => philosopher.id === id) || modularPhilosophers.get(id); if (!selectedPhilosopher) return; const modular = modularPhilosophers.get(id); document.getElementById("tab-encyclopedia").classList.add("hidden"); document.getElementById("detail-view").classList.remove("hidden"); document.getElementById("dedicated-avatar").textContent = selectedPhilosopher.name.split(" ").map(word => word[0]).slice(0, 2).join(""); document.getElementById("dedicated-era").textContent = selectedPhilosopher.era; document.getElementById("dedicated-name").textContent = selectedPhilosopher.name; document.getElementById("dedicated-years").textContent = selectedPhilosopher.years; document.getElementById("dedicated-quote").textContent = `"${selectedPhilosopher.quote}"`; document.getElementById("dedicated-sections").innerHTML = modular ? `<section class="reading-section"><p class="eyebrow">Academic dossier</p><div class="reading-copy space-y-4">${modular.contentHtml}</div></section>` : `<section class="reading-section"><p class="eyebrow">Context</p><h3>Latar Belakang dan Genealogi</h3><div class="reading-copy"><p>${selectedPhilosopher.background}</p><p>${selectedPhilosopher.genealogy}</p></div></section>`; document.getElementById("dedicated-copy").dataset.quote = selectedPhilosopher.quote; document.getElementById("dedicated-share").dataset.quote = selectedPhilosopher.quote; window.scrollTo({ top: 0, behavior: "smooth" }); }
window.philosophersData = philosophersData;
Object.assign(window, { switchTab, toggleTheme, openAuthModal, closeAuthModal, switchAuthTab, handleAuth, analyzeArgument, analyzeSyllogism, copyQuote, shareQuote, closeDedicatedDetail, copyDedicatedQuote, shareDedicatedQuote, showPhilosopherDetail });
function showOldDetail3(id) { selectedPhilosopher = philosophers.find(philosopher => philosopher.id === id); if (!selectedPhilosopher) return; document.getElementById("tab-encyclopedia").classList.add("hidden"); document.getElementById("detail-view").classList.remove("hidden"); document.getElementById("dedicated-avatar").textContent = selectedPhilosopher.name.split(" ").map(word => word[0]).slice(0, 2).join(""); document.getElementById("dedicated-era").textContent = selectedPhilosopher.era; document.getElementById("dedicated-name").textContent = selectedPhilosopher.name; document.getElementById("dedicated-years").textContent = selectedPhilosopher.years; document.getElementById("dedicated-quote").textContent = `"${selectedPhilosopher.quote}"`; document.getElementById("dedicated-sections").innerHTML = `<section class="reading-section"><p class="eyebrow">01 / Context</p><h3>Latar Belakang dan Kondisi Sosial-Politik</h3><p>${selectedPhilosopher.background}</p></section><section class="reading-section"><p class="eyebrow">02 / Genealogy</p><h3>Genealogi dan Akar Pemikiran</h3><p>${selectedPhilosopher.genealogy}</p></section><section class="reading-section"><p class="eyebrow">03 / Radical anatomy</p><h3>Bedah Cabang Pemikiran Radikal</h3><div class="branch-grid">${selectedPhilosopher.branches.map((branch, index) => `<article><span>0${index + 1}</span><p>${branch}</p></article>`).join("")}</div></section><section class="reading-section"><p class="eyebrow">04 / Magnum opus</p><h3>Katalog Literatur dan Karya Utama</h3><div class="works-list">${selectedPhilosopher.works.map(work => `<p><i class="fa-solid fa-book-open"></i>${work}</p>`).join("")}</div></section>`; document.getElementById("dedicated-copy").dataset.quote = selectedPhilosopher.quote; document.getElementById("dedicated-share").dataset.quote = selectedPhilosopher.quote; window.scrollTo({top: 0, behavior: "smooth"}); }
function closeDedicatedDetail() { selectedPhilosopher = null; document.getElementById("detail-view").classList.add("hidden"); document.getElementById("tab-encyclopedia").classList.remove("hidden"); renderPhilosophers(); window.scrollTo({top: 0, behavior: "smooth"}); }
function copyDedicatedQuote() { const quote = document.getElementById("dedicated-copy").dataset.quote; navigator.clipboard?.writeText(quote); }
function shareDedicatedQuote() { const quote = document.getElementById("dedicated-share").dataset.quote; if (navigator.share) navigator.share({title: "Philosofun", text: quote}); else navigator.clipboard?.writeText(quote); }

const academicDossiers = {
  "Al-Farabi": {
    background: "Al-Farabi bekerja dalam dunia Abbasiyah abad ke-10 yang secara politik mengalami fragmentasi, meskipun Baghdad tetap menjadi pusat simbolik ilmu dan penerjemahan. Munculnya kekuasaan Hamdanid di Aleppo di bawah Saif al-Dawla memperlihatkan bahwa otoritas khalifah tidak identik lagi dengan kendali administratif yang utuh. Dalam lanskap yang diisi patronase istana, rivalitas dinasti, dan perdebatan tentang legitimasi, ilmu tidak pernah sepenuhnya netral: klasifikasi pengetahuan sekaligus menyusun hierarki kewibawaan sosial.",
    genealogy: "Tradisi Al-Farabi dibentuk oleh perjumpaan dengan teks Yunani yang masuk melalui jaringan penerjemah Kristen berbahasa Suryani, termasuk lingkungan Yuhanna ibn Haylan. Gelar al-Mu'allim al-Thani, Guru Kedua setelah Aristoteles, bukan sekadar pujian akademik: ia menunjuk pada proyek untuk menjadikan logika Organon sebagai tata bahasa universal bagi demonstrasi, politik, dan teologi. Al-Farabi juga membaca Plato dan Aristoteles melalui lapisan Neoplatonis Plotinus serta Proclus, lalu menguji bagaimana emanasi dan intelek dapat dibicarakan tanpa menghapus transendensi wahyu.",
    branches: [
      { title: "Metafisika dan teori emanasi", paragraphs: ["Dalam metafisika Al-Farabi, Wajib al-Wujud bukan hanya nama bagi sebab pertama, melainkan prinsip yang dari dirinya sendiri tidak mungkin tidak ada. Karena Yang Niscaya sepenuhnya sederhana dan tidak menerima perubahan, hubungan-Nya dengan multiplisitas tidak dipahami sebagai tindakan temporal, melainkan sebagai faid atau emanasi yang tertib. Intelek Pertama mengetahui dirinya dan sumbernya; dari struktur pengetahuan itu muncul jenjang intelek kosmis, sebuah arsitektur yang menerangkan bagaimana kesatuan ilahi dapat menjadi dasar bagi keragaman dunia tanpa menjadikan Tuhan terseret ke dalam perubahan material.", "Rangkaian sepuluh intelek berakhir pada al-'Aql al-Fa'al, Intelek Aktif, yang berhubungan langsung dengan alam sublunar. Intelek Aktif memberi bentuk inteligibel kepada potensi akal manusia dan menjelaskan mengapa pengetahuan manusia dapat berpartisipasi dalam tatanan kosmos. Kosmologi ini tidak boleh dibaca sebagai astronomi modern; ia adalah teori mediasi ontologis: dunia ilahi, jiwa manusia, wahyu, dan alam inderawi dihubungkan melalui gradasi aktualitas dan intelligibility."] },
      { title: "Al-Madinah al-Fadilah dan filsafat politik", paragraphs: ["Dalam Ara' Ahl al-Madinah al-Fadilah, negara utama bukan sekadar perangkat administratif, tetapi bentuk sosial dari kosmologi. Rais Awwal adalah pemimpin yang menggabungkan pengetahuan demonstratif, kebajikan praktis, kemampuan imajinatif, dan kapasitas memimpin. Pada figur filsuf-nabi, Intelek Aktif diterima bukan sebagai data proposisional biasa, melainkan sebagai bentuk pengetahuan yang dapat diterjemahkan ke dalam simbol, hukum, ritus, dan pendidikan bagi masyarakat yang tidak semuanya mampu mengikuti burhan filosofis.", "Kontrasnya adalah al-madinah al-jahiliyyah: kota kebutuhan dasar (dharuriyyah) mengejar kelangsungan hidup, kota kekayaan (naddalah) menjadikan akumulasi sebagai tujuan, sedangkan kota kebebasan liar (hurriyyah) menganggap preferensi sesaat sebagai ukuran tertinggi. Kritik Al-Farabi di sini bersifat struktural. Kerusakan politik terjadi ketika hasrat parsial sebuah kelompok menyamar sebagai tujuan kebahagiaan universal; negara utama mengoreksinya melalui pendidikan jiwa, pembagian fungsi, dan orientasi teleologis pada sa'adah."] },
      { title: "Epistemologi, jiwa, dan teori intelek", paragraphs: ["Teori intelek Al-Farabi bergerak dari 'aql bi al-quwwah, akal potensial yang mampu menerima bentuk, menuju 'aql bi al-fi'l, akal aktual yang telah menguasai bentuk-bentuk intelligibel. Pada tingkat lebih tinggi terdapat 'aql mustafad, akal perolehan, ketika aktivitas berpikir manusia memiliki kontinuitas dengan Intelek Aktif. Pengetahuan karena itu bukan salinan pasif dari benda; ia adalah aktualisasi suatu kapasitas jiwa melalui abstraksi, bahasa, demonstrasi, dan latihan intelektual.", "Wahyu diterangkan melalui kesempurnaan al-quwwah al-mutakhayyilah, daya imajinatif yang mampu menerima bentuk-bentuk dari Intelek Aktif dan menyusunnya dalam citra, perumpamaan, serta perintah yang dapat dipahami komunitas. Filsuf menerima realitas secara demonstratif, sedangkan nabi menerimanya melalui imajinasi yang sempurna dan mengartikulasikannya secara persuasif. Perbedaan itu adalah perbedaan modus representasi, bukan dua realitas yang saling bertentangan."] },
      { title: "Harmonisasi Plato dan Aristoteles", paragraphs: ["Kitab al-Jam' baina Ra'yay al-Hakimain mencoba menunjukkan bahwa pertentangan antara Plato dan Aristoteles sering dihasilkan oleh pembacaan dangkal, atribusi yang meragukan, atau perbedaan gaya argumentasi. Al-Farabi menempatkan keduanya dalam horizon pencarian yang sama: sebab pertama, jiwa, kebajikan, dan tatanan politik. Strateginya bukan menghapus perbedaan, melainkan membedakan lapisan terminologis dan tujuan demonstrasi.", "Agama dan filsafat kemudian dipahami sebagai dua cara menghadirkan satu kebenaran. Filsafat bekerja melalui burhan dan definisi kausal, sedangkan agama memakai bahasa simbolis, alegoris, dan persuasif agar kebenaran dapat menjadi kebiasaan hidup masyarakat. Model ini memberi filsafat ruang legitimasi di dunia Islam tanpa harus menjadikan wahyu sekadar mitologi; ia juga memberi agama fungsi politik-pedagogis yang tidak dapat digantikan oleh argumen abstrak."] }
    ],
    works: [
      { title: "Ara' Ahl al-Madinah al-Fadilah", analysis: "Karya ini menghubungkan tata negara ideal dengan metafisika emanasi. Bentuk pemerintahan tidak dinilai hanya dari prosedur pergantian penguasa, tetapi dari tujuan terakhir yang ditanamkan ke dalam jiwa warga. Kota utama adalah komunitas yang mengorganisasi pendidikan, hukum, ekonomi, dan simbol agama untuk mengarahkan manusia pada kebahagiaan intelektual; daftar kota rusak memperlihatkan bagaimana kebutuhan, kekayaan, kehormatan, atau kebebasan tanpa orientasi dapat menjadi ideologi politik." },
      { title: "Ihsa' al-'Ulum", analysis: "Klasifikasi ilmu ini menyusun bahasa, logika, matematika, ilmu alam, metafisika, politik, fikih, dan kalam dalam urutan pedagogis. Logika menjadi instrumen untuk membedakan demonstrasi, dialektika, retorika, dan sofistika; ilmu-ilmu partikular lalu menemukan tempatnya dalam keseluruhan epistemik. Buku ini penting karena memperlakukan kurikulum sebagai teori tentang jenis-jenis objek, cara mengetahui, dan fungsi sosial pengetahuan." },
      { title: "Kitab al-Musiqa al-Kabir", analysis: "Al-Farabi menganalisis musik melalui rasio interval, struktur ritme, praktik pertunjukan, dan dampak afektifnya. Musik tidak direduksi menjadi hiburan: ia menjadi teknologi pembentukan jiwa yang dapat mengatur temperamen, membangun solidaritas, dan membantu terapi. Matematika memberi ketepatan pada hubungan nada, sementara pengalaman pendengaran menjelaskan bagaimana bentuk itu bekerja pada tubuh dan emosi." }
    ]
  },
  "Aristotle": {
    background: "Aristotle hidup di antara polis Yunani dan ekspansi Makedonia. Pengalaman sebagai orang Stagira, murid Akademia, pendiri Lyceum, dan pengamat konstitusi membuat filsafatnya selalu bergerak antara analisis konseptual dan penelitian empiris. Perubahan politik setelah perang Peloponnesos menimbulkan pertanyaan tentang apakah manusia dapat mencapai eudaimonia dalam institusi yang stabil, dan apakah bentuk negara bisa dinilai tanpa mengabaikan kondisi material warga.",
    genealogy: "Ia mewarisi pertanyaan Socrates tentang definisi dan pendidikan moral, serta metafisika Plato tentang bentuk. Kritik Aristoteles terhadap chorismos, pemisahan bentuk dari benda, menggeser filsafat menuju analisis imanen: bentuk berada dalam substansi dan menjelaskan aktualitasnya. Tradisinya kemudian dibaca ulang oleh Ibn Sina, Aquinas, kaum empiris, dan ilmu biologi modern, meskipun teleologi serta teori politiknya juga dikritik karena hierarki sosialnya.",
    branches: [
      { title: "Metafisika dan hylomorphism", paragraphs: ["Hylomorphism menyatakan bahwa benda alamiah merupakan kesatuan hyle dan morphe, materi dan bentuk. Materi murni adalah kapasitas, sedangkan bentuk adalah prinsip aktualisasi yang membuat sesuatu menjadi jenis benda tertentu. Dengan cara ini Aristotle menolak baik reduksi realitas menjadi materi tanpa struktur maupun Platonisme yang menempatkan bentuk di dunia terpisah. Substansi konkret menjadi titik temu antara apa yang dapat berubah dan pola intelligibel yang membuat perubahan dapat dipahami.", "Empat sebab - material, formal, efisien, dan final - memperluas pertanyaan tentang 'mengapa'. Sebab final bukan selalu maksud sadar, melainkan arah internal suatu proses menuju aktualitasnya. Metafisika ini menjelaskan gerak melalui pasangan potentia dan actus; perubahan bukan penciptaan dari nihil, tetapi aktualisasi kapasitas yang ditata oleh bentuk. Di sinilah fisika, biologi, dan ontologi bertemu dalam satu kerangka teleologis."] },
      { title: "Jiwa dan psyche", paragraphs: ["Dalam De Anima, jiwa bukan hantu yang menghuni tubuh, melainkan entelecheia pertama dari tubuh alamiah yang memiliki kehidupan secara potensial. Jiwa vegetatif menjelaskan nutrisi dan reproduksi, jiwa sensitif menjelaskan persepsi dan gerak, sedangkan jiwa rasional memungkinkan logos dan deliberasi. Pembagian ini tidak identik dengan tiga benda di dalam manusia; ia adalah analisis fungsi dan tingkat aktualitas organisme.", "Pengetahuan dimulai dari aisthesis, persepsi, tetapi tidak berhenti pada kesan partikular. Ingatan, pengalaman, dan abstraksi memungkinkan nous menangkap bentuk universal. Ketegangan antara intelek aktif dan pasif kemudian memunculkan sejarah tafsir panjang: apakah intelek aktif bersifat bagian jiwa individual, atau prinsip kosmis yang membuat inteligibilitas mungkin."] },
      { title: "Retorika dan seni persuasi", paragraphs: ["Retorika bagi Aristotle bukan manipulasi kosong, tetapi techne untuk menemukan sarana persuasi yang tersedia dalam setiap perkara. Ethos membangun kredibilitas pembicara, pathos mengatur keadaan afektif pendengar, dan logos menyusun enthymeme, yaitu silogisme retoris yang bekerja dari premis yang dianggap masuk akal oleh publik. Analisis ini menjelaskan mengapa argumen tidak pernah hanya berupa proposisi abstrak.", "Karena retorika beroperasi dalam polis, ia memiliki dimensi etis dan politik. Pembicara yang baik harus mengetahui karakter audiens, jenis bukti, waktu, dan tujuan pidato, tetapi juga bertanggung jawab atas kemungkinan penyalahgunaan. Dengan membedakan retorika dari sofistika, Aristotle mempertahankan persuasi sebagai kemampuan sipil sambil menuntut hubungan antara logos dan kebenaran."] },
      { title: "Politik dan negara", paragraphs: ["Politik dimulai dari observasi bahwa manusia adalah zoon politikon: bukan sekadar hewan yang hidup berkelompok, tetapi makhluk yang memiliki logos untuk membedakan adil dan tidak adil. Polis bukan kontrak artifisial yang ditambahkan pada individu yang sudah lengkap; ia adalah lingkungan tempat kapasitas manusia menjadi aktual melalui hukum, pendidikan, partisipasi, dan persahabatan sipil.", "Klasifikasi politeia, aristokrasi, dan monarki bersama bentuk-bentuk menyimpangnya menunjukkan bahwa Aristotle menilai rezim melalui pertanyaan siapa yang memerintah dan untuk kepentingan siapa. Ia mengusulkan pentingnya kelas menengah dan konstitusi campuran karena stabilitas lahir dari penyeimbangan kepentingan. Namun, eksklusi perempuan, budak, dan pekerja manual memperlihatkan batas historis universalisme politiknya."] },
      { title: "Etika kebajikan dan eudaimonia", paragraphs: ["Eudaimonia bukan perasaan senang sesaat, melainkan flourishing yang diwujudkan sepanjang keseluruhan hidup melalui aktivitas jiwa yang sesuai dengan kebajikan. Kebajikan etis terbentuk oleh habituasi: manusia menjadi adil dengan melakukan tindakan adil berulang kali, bukan dengan mengetahui definisi keadilan saja. Prohairesis, pilihan deliberatif, menghubungkan pengetahuan praktis dengan tindakan dalam situasi konkret.", "Golden mean tidak berarti kompromi matematis antara dua angka, melainkan ketepatan relatif terhadap kita dan keadaan. Keberanian berada antara pengecut dan nekat, tetapi ukuran itu membutuhkan phronesis, kebijaksanaan praktis, untuk membaca detail situasi. Karena itu etika Aristotle tidak dapat direduksi menjadi daftar aturan; ia adalah teori pembentukan karakter, persepsi moral, dan penilaian yang matang."] }
    ],
    works: [
      { title: "Metaphysics", analysis: "Kumpulan buku ini menyelidiki being qua being, substansi, sebab, potensialitas, dan aktualitas. Perdebatan tentang ousia bergerak dari benda konkret menuju pertanyaan tentang bentuk dan sebab pertama, sehingga metafisika berfungsi sebagai ilmu tentang kondisi paling umum bagi segala ilmu lain." },
      { title: "Nicomachean Ethics", analysis: "Aristotle membangun etika dari tujuan tindakan, kebahagiaan, kebajikan, pilihan, kelemahan kehendak, persahabatan, dan kontemplasi. Buku ini menunjukkan bahwa moralitas bukan kalkulasi terisolasi, melainkan praktik sosial yang membentuk karakter dan membutuhkan institusi politik yang layak." },
      { title: "Politics", analysis: "Politics menganalisis keluarga, perbudakan, kewargaan, bentuk konstitusi, revolusi, pendidikan, dan konstitusi terbaik yang mungkin. Kekuatan analisisnya terletak pada pertemuan antara tipologi normatif dan studi atas konstitusi aktual, walaupun kategorinya tetap dibatasi struktur sosial Yunani." }
    ]
  },
  "Immanuel Kant": {
    background: "Kant menulis pada puncak Aufklarung, ketika keberhasilan mekanika Newton mendorong kepercayaan pada rasio, sementara perang agama dan perdebatan metafisika menunjukkan rapuhnya kepastian filosofis. Rasionalisme kontinental mengklaim prinsip bawaan akal, empirisme Inggris menekankan pengalaman, dan Hume mengguncang gagasan kausalitas. Proyek Kant lahir sebagai usaha menyelidiki syarat kemungkinan pengetahuan, bukan sekadar memilih salah satu kubu.",
    genealogy: "Kant menerima dorongan empiris dari Hume, ketertiban sistematis dari Leibniz-Wolff, dan problem kebebasan dari Rousseau. Revolusi Copernican-nya membalik pertanyaan: bukan hanya bagaimana pikiran menyesuaikan diri dengan objek, tetapi bagaimana objek pengalaman muncul melalui bentuk sensibilitas dan kategori pemahaman. Hegel dan idealisme Jerman mengembangkan sekaligus mengkritik proyek ini, sementara filsafat analitik dan kritis terus memperdebatkan status noumena.",
    branches: [
      { title: "Epistemologi transendental", paragraphs: ["Kant membedakan sensibility dan understanding. Ruang dan waktu bukan benda yang ditemukan setelah pengalaman, melainkan bentuk a priori yang membuat intuisi inderawi dapat tersusun. Kategori seperti kausalitas, substansi, dan kesatuan kemudian mengorganisasi manifold pengalaman menjadi objek yang dapat dinilai. Karena itu pengetahuan empiris tetap objektif, tetapi objektivitasnya adalah objektivitas bagi makhluk yang memiliki kondisi transendental tertentu.", "Perbedaan fenomena dan noumena bukan lisensi untuk berspekulasi tentang dunia rahasia. Ia adalah batas metodologis: kita mengenal benda sebagaimana tampil dalam kerangka pengalaman, sedangkan thing-in-itself menandai apa yang tidak dapat dikonversi menjadi objek pengetahuan teoretis. Antinomi kosmologi menunjukkan rasio jatuh ke kontradiksi ketika memakai kategori di luar pengalaman yang mungkin."] },
      { title: "Etika dan imperatif kategoris", paragraphs: ["Moralitas Kant tidak didasarkan pada akibat, kecenderungan, atau kebahagiaan yang berubah-ubah, tetapi pada good will yang bertindak karena kewajiban. Imperatif kategoris memerintahkan: bertindak hanya menurut maksim yang dapat sekaligus dikehendaki sebagai hukum universal. Universalitas di sini bukan aturan statistik; ia menguji apakah prinsip tindakan menghormati rasionalitas semua agen.", "Formula humanity memperdalam tuntutan itu: manusia harus selalu diperlakukan sebagai tujuan pada dirinya, tidak pernah semata-mata sebagai alat. Autonomi berarti subjek rasional memberi hukum moral kepada dirinya sendiri, tetapi bukan berarti bebas melakukan apa saja. Kebebasan justru tampak sebagai kemampuan tunduk pada hukum yang dapat dipertanggungjawabkan secara universal, sebuah konsep yang membentuk teori martabat modern."] },
      { title: "Estetika dan teleologi", paragraphs: ["Dalam Critique of Judgment, penilaian keindahan tidak bergantung pada konsep objektif seperti pengetahuan ilmiah, tetapi juga tidak sesubjektif selera privat. Rasa pleasure yang disertai disinterestedness mengklaim communicability universal: kita mengharapkan orang lain dapat berbagi penilaian, meski tidak dapat memaksanya melalui bukti deduktif. Free play antara imajinasi dan understanding menjelaskan pengalaman bentuk yang terasa bermakna.", "Teleologi kemudian menjadi cara reflektif memahami organisme dan alam tanpa menyatakan bahwa alam secara ilmiah dibuat demi tujuan tertentu. Organisme dipahami seolah-olah bagian-bagiannya saling menjadi tujuan dan sarana. Prinsip ini membantu menjembatani determinisme alam dengan dunia kebebasan moral tanpa mengubah tujuan reflektif menjadi fakta metafisik."] },
      { title: "Politik, sejarah, dan perdamaian", paragraphs: ["Kant melihat sejarah dari sudut regulatif sebagai perkembangan kapasitas kebebasan dan institusi hukum. Antagonisme sosial dapat memaksa manusia membangun tatanan sipil yang lebih rasional, meski sejarah aktual tidak otomatis bermoral. Dalam Toward Perpetual Peace, republik, federasi negara, dan hukum kosmopolitan menjadi syarat politik bagi pengurangan perang.", "Kosmopolitanisme Kant penting sekaligus problematis. Ia memberi dasar normatif bagi kewargaan dunia dan hak hospitalitas, tetapi bahasa progresnya perlu dibaca bersama konteks kolonial Eropa. Pembacaan kritis modern mempertahankan tuntutan universalitasnya sambil menolak menjadikan pengalaman Eropa sebagai satu-satunya ukuran sejarah manusia."] }
    ],
    works: [
      { title: "Critique of Pure Reason", analysis: "Buku ini menguji kemungkinan matematika, ilmu alam, dan metafisika melalui estetika transendental, analitika, dan dialektika. Kant tidak membatalkan metafisika, melainkan memindahkannya menjadi kritik atas kapasitas dan batas rasio yang menghasilkan klaim metafisik." },
      { title: "Groundwork of the Metaphysics of Morals", analysis: "Groundwork mencari prinsip tertinggi moralitas dari konsep good will, kewajiban, hukum universal, dan otonomi. Formulasi imperatif kategoris dihadirkan sebagai beberapa sudut pandang atas hukum rasional yang sama, bukan sebagai aturan moral yang terpisah-pisah." },
      { title: "Critique of Judgment", analysis: "Karya ini menjembatani dua kritik sebelumnya melalui estetika dan teleologi. Penilaian keindahan, pengalaman sublim, seni, dan organisme menunjukkan bagaimana manusia membutuhkan prinsip refleksi ketika konsep determinatif tidak cukup, tanpa mengklaim pengetahuan dogmatis." }
    ]
  },
  "Michel Foucault": {
    background: "Foucault menulis setelah perang dunia, Holocaust, ekspansi negara administratif, dan berkembangnya psikiatri, penjara, serta ilmu sosial. Ia melihat bahwa modernitas tidak hanya menindas lewat hukum yang melarang, tetapi juga memproduksi kategori normal, menyusun arsip, mengukur tubuh, dan membuat individu mengawasi dirinya sendiri. Konteks ini membuat sejarah kegilaan, kriminalitas, dan seksualitas menjadi sejarah politik tentang siapa yang boleh menjadi subjek.",
    genealogy: "Foucault mengambil dorongan dari Nietzsche dan metode genealogi: mencari kontingensi, konflik, dan praktik material di balik sesuatu yang tampak alamiah. Ia mengkritik humanisme yang menganggap manusia universal sebagai titik awal netral, tetapi juga menolak determinisme sederhana. Kritik terhadap strukturalisme, fenomenologi, psikoanalisis, dan Marxisme membuatnya mengembangkan archaeology of knowledge, dispositif, governmentality, dan biopolitics.",
    branches: [
      { title: "Arkeologi wacana", paragraphs: ["Arkeologi tidak mencari niat pengarang tersembunyi atau makna abadi di balik teks. Ia memetakan aturan yang menentukan apa yang dapat dikatakan, siapa yang dianggap memiliki otoritas, jenis objek apa yang dapat dibicarakan, dan konsep apa yang dapat berfungsi sebagai pengetahuan pada suatu periode. Episteme bukan teori sadar yang dimiliki masyarakat, melainkan konfigurasi historis yang membuat ujaran tertentu tampak masuk akal.", "Dengan metode ini, perubahan ilmiah tidak hanya dipahami sebagai akumulasi fakta. Diskursus kedokteran, ekonomi, atau psikiatri mengubah cara objek muncul sekaligus mengubah posisi subjek yang mengucapkannya. Kebenaran memiliki sejarah institusional: laboratorium, rumah sakit, universitas, arsip, dan prosedur verifikasi ikut membentuk apa yang disebut benar."] },
      { title: "Disiplin tubuh dan panoptikon", paragraphs: ["Dalam Discipline and Punish, Foucault menelusuri pergeseran dari hukuman spektakuler atas tubuh menuju disiplin yang bekerja secara halus dan terus-menerus. Waktu, ruang, ujian, catatan, ranking, dan pemeriksaan memecah tubuh menjadi unit yang dapat dibandingkan. Normalization menjadikan norma statistik dan moral sebagai alat intervensi, bukan sekadar deskripsi.", "Panoptikon Bentham berfungsi sebagai diagram kuasa: kemungkinan selalu dilihat membuat tahanan menginternalisasi tatapan pengawas. Yang penting bukan bangunan penjara tertentu, melainkan prinsip bahwa individu menjadi prinsip pengawasan bagi dirinya sendiri. Sekolah, barak, pabrik, rumah sakit, dan platform digital dapat mengulang logika ini dengan cara yang berbeda."] },
      { title: "Seksualitas dan biopolitik", paragraphs: ["Foucault menolak hipotesis represif bahwa modernitas terutama membungkam seks. Sejak abad ke-19, seks justru dibicarakan secara berlimpah melalui kedokteran, pendidikan, hukum, pengakuan, dan psikologi. Scientia sexualis mengubah hasrat menjadi objek pemeriksaan dan identitas, sehingga subjek didorong untuk mengatakan kebenaran tentang dirinya kepada otoritas.", "Biopolitik bekerja pada populasi melalui statistik kelahiran, kesehatan, kematian, ras, dan produktivitas, sementara disiplin bekerja pada tubuh individual. Keduanya bertemu dalam governmentality, yaitu cara mengarahkan perilaku dengan membentuk pilihan, risiko, dan norma. Kuasa tidak hanya berpusat pada negara; ia beredar melalui jaringan praktik yang memungkinkan dan membatasi tindakan."] },
      { title: "Subjek, etika, dan resistensi", paragraphs: ["Jika subjek diproduksi oleh relasi kuasa-pengetahuan, kritik tidak berarti menemukan diri yang murni di luar kuasa. Foucault menggeser etika menuju practices of the self: latihan, gaya hidup, dan hubungan reflektif dengan diri yang memungkinkan seseorang mengubah cara ia dibentuk. Etika adalah kerja pembentukan diri, bukan penemuan esensi batin yang tetap.", "Pernyataan bahwa di mana ada kuasa di situ ada resistensi berarti resistensi bukan kekuatan eksternal yang menunggu di luar sistem. Ia muncul pada titik-titik yang sama tempat subjek diatur, diukur, dan dinormalisasi. Genealogi karena itu bukan ramalan revolusi, melainkan cara memperlihatkan bahwa institusi yang tampak niscaya memiliki sejarah dan dapat dibuat berbeda."] }
    ],
    works: [
      { title: "Discipline and Punish", analysis: "Foucault mengubah sejarah penjara menjadi analisis tentang lahirnya masyarakat disipliner. Eksekusi publik, reformasi hukuman, panoptikon, pemeriksaan, dan normalisasi dibaca sebagai teknik yang memproduksi tubuh berguna sekaligus patuh." },
      { title: "The History of Sexuality, Volume I", analysis: "Buku ini mengkritik anggapan bahwa kuasa hanya menekan seksualitas. Foucault menunjukkan bagaimana pengakuan, psikiatri, hukum, keluarga, dan demografi memproduksi wacana seks sehingga individu menjadi subjek yang harus menafsirkan dan menyatakan hasratnya." },
      { title: "The Archaeology of Knowledge", analysis: "Karya metodologis ini menjelaskan bagaimana formasi diskursif, enunciative rules, arsip, dan discontinuity memungkinkan sejarah pengetahuan ditulis tanpa mereduksinya pada niat individu atau evolusi linear ide." }
    ]
  }
};

function getAcademicProfile(philosopher) { return academicDossiers[philosopher.name] || { background: philosopher.background, genealogy: philosopher.genealogy, branches: philosopher.branches.map(branch => ({ title: "Kajian pemikiran", paragraphs: [branch, "Pembahasan ini dapat dibaca sebagai titik awal untuk menelusuri hubungan antara istilah teknis, konteks historis, dan konsekuensi normatifnya dalam keseluruhan filsafat tokoh tersebut."] })), works: philosopher.works.map(work => ({ title: work.split(" - ")[0], analysis: work })) }; }
function showFallbackDetail(id) { selectedPhilosopher = philosophers.find(philosopher => philosopher.id === id); if (!selectedPhilosopher) return; const profile = getAcademicProfile(selectedPhilosopher); document.getElementById("tab-encyclopedia").classList.add("hidden"); document.getElementById("detail-view").classList.remove("hidden"); document.getElementById("dedicated-avatar").textContent = selectedPhilosopher.name.split(" ").map(word => word[0]).slice(0, 2).join(""); document.getElementById("dedicated-era").textContent = selectedPhilosopher.era; document.getElementById("dedicated-name").textContent = selectedPhilosopher.name; document.getElementById("dedicated-years").textContent = selectedPhilosopher.years; document.getElementById("dedicated-quote").textContent = `"${selectedPhilosopher.quote}"`; document.getElementById("dedicated-sections").innerHTML = `<section class="reading-section"><p class="eyebrow">01 / Context</p><h3>Latar Belakang dan Kondisi Sosial-Politik</h3><div class="reading-copy"><p>${profile.background}</p></div></section><section class="reading-section"><p class="eyebrow">02 / Genealogy</p><h3>Genealogi dan Akar Pemikiran</h3><div class="reading-copy"><p>${profile.genealogy}</p></div></section><section class="reading-section"><p class="eyebrow">03 / Radical anatomy</p><h3>Bedah Cabang Pemikiran</h3><div class="branch-list">${profile.branches.map((branch, index) => `<article><span class="branch-number">${String(index + 1).padStart(2, "0")}</span><h4>${branch.title}</h4><div class="reading-copy space-y-4">${branch.paragraphs.map(paragraph => `<p>${paragraph}</p>`).join("")}</div></article>`).join("")}</div></section><section class="reading-section"><p class="eyebrow">04 / Magnum opus</p><h3>Katalog Literatur dan Karya Utama</h3><div class="works-list">${profile.works.map(work => `<article><h4>${work.title}</h4><div class="reading-copy"><p>${work.analysis}</p></div></article>`).join("")}</div></section>`; document.getElementById("dedicated-copy").dataset.quote = selectedPhilosopher.quote; document.getElementById("dedicated-share").dataset.quote = selectedPhilosopher.quote; window.scrollTo({ top: 0, behavior: "smooth" }); }


